CREATE OR REPLACE FUNCTION public.set_planned1_date()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  -- Only set if not already provided
  if NEW."Planned 1" is null then
    NEW."Planned 1" := current_date;
  end if;

  return NEW;
end;
$function$

