CREATE OR REPLACE FUNCTION public.set_planned2_from_actual2()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  -- If Actual 2 is set and Planned 2 is null
  if NEW."Actual 2" is not null and NEW."Planned 2" is null then
    NEW."Planned 2" := NEW."Actual 2";
  end if;

  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_new_composition_no()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    max_no INTEGER;
BEGIN
    -- Only generate a new number if 'Composition No.' is not already provided
    IF NEW."Composition No." IS NULL OR NEW."Composition No." = '' THEN
        -- Extract the highest numeric part from existing entries matching the 'CN-XXX' pattern
        SELECT COALESCE(
            MAX(
                CAST(SUBSTRING("Composition No." FROM '^CN-(\d+)$') AS INTEGER)
            ), 
            0
        )
        INTO max_no
        FROM public.costing_response
        WHERE "Composition No." ~ '^CN-\d+$';

        -- Set the new value: CN- followed by incremented number padded to 3 digits (e.g., CN-001)
        NEW."Composition No." := 'CN-' || LPAD((max_no + 1)::TEXT, 3, '0');
    END IF;

    RETURN NEW;
END;
$function$
